package org.beckenburg;

import javax.swing.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import org.beckenburg.editor.*;

/** Human UV controls in the separate material window, not an alternate scene editor. */
public final class AssetImportUvGuiTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static Object field(Object owner,String name)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    private static void button(AssetImportDialog ui,String name)throws Exception{((JButton)field(ui,name)).doClick();}
    private static boolean ready(AssetImportDialog ui){try{return !((Boolean)field(ui,"busy"))&&((JButton)field(ui,"apply")).isEnabled();}catch(Exception e){throw new RuntimeException(e);}}
    private static boolean reviewed(AssetImportDialog ui){try{return !((Boolean)field(ui,"busy"))&&field(ui,"modelingPreview")!=null;}catch(Exception e){throw new RuntimeException(e);}}
    private static void await(java.util.function.BooleanSupplier condition)throws Exception{long end=System.nanoTime()+30_000_000_000L;while(System.nanoTime()<end){var done=new java.util.concurrent.atomic.AtomicBoolean();SwingUtilities.invokeAndWait(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(20);}throw new AssertionError("Human UV operation did not complete");}
    private static void capture(AssetImportDialog ui,Path path)throws Exception{var content=((JDialog)field(ui,"materialDialog")).getContentPane();var image=new BufferedImage(content.getWidth(),content.getHeight(),BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();try{content.printAll(g);}finally{g.dispose();}ImageIO.write(image,"png",path.toFile());}
    private static void select(AssetImportDialog ui)throws Exception{
        ((JComboBox<?>)field(ui,"meshView")).setSelectedItem(EditorMeshPicking.Projection.FRONT);((JComboBox<?>)field(ui,"selectionMode")).setSelectedItem("FACE");var canvas=(JPanel)field(ui,"preview");int w=ui.workingViewportWidth(),h=Math.max(180,canvas.getHeight());double scale=Math.min(w-26,h-36);
        canvas.dispatchEvent(new MouseEvent(canvas,MouseEvent.MOUSE_PRESSED,System.currentTimeMillis(),0,w/2-(int)Math.round(.25*scale),h/2+(int)Math.round(.25*scale),1,false,MouseEvent.BUTTON1));check(((EditorMeshPicking.Hit)field(ui,"selectedHit")).faceId()==0,"Actual native face picked");ui.openMaterials();((JTabbedPane)field(ui,"materialTools")).setSelectedIndex(1);
    }
    private static void verifyRuntime(String id,EditorTopologyProject p)throws Exception{
        var actual=GlbProps.model(id).triangles();var expected=p.mesh().triangles();check(actual.size()==expected.size(),"Actual runtime UV triangle count");
        for(int i=0;i<actual.size();i++){var a=List.of(actual.get(i).a(),actual.get(i).b(),actual.get(i).c());var b=List.of(expected.get(i).a(),expected.get(i).b(),expected.get(i).c());for(int j=0;j<3;j++){var x=a.get(j);var y=b.get(j);check(x.u()==(double)(float)y.u()&&x.v()==(double)(float)y.v()&&x.x()==y.x()&&x.y()==y.y()&&x.z()==y.z(),"Every edited UV and unchanged position reaches actual runtime");check(Math.abs(x.nz()-1)<1e-6,"Authored raw normal remains correct at runtime");}}
        var corner=actual.get(0).a();check(GlbProps.sample(actual.get(0).material(),corner.u(),corner.v())==0xffff00,"Original asymmetric texture responds to actual UV half-width move");check(EditorTopologyProject.open(ImportedAssetLibrary.root().resolve(id+".authoring.btop")).snapshot().equals(p.snapshot()),"Publication archives exact edited native UVs/materials/normals");
    }
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("human-uv-");String oldHome=System.getProperty("user.home");System.setProperty("user.home",root.toString());Path output=Path.of("build/editor-agent-evidence").toAbsolutePath();Files.createDirectories(output);Path source=root.resolve("uv.obj");
        Files.writeString(source,"mtllib paint.mtl\nusemtl Paint\no panel\nv 0 0 0\nv 1 0 0\nv 0 1 0\nv 1 1 0\nvt 0 0\nvt 1 0\nvt 0 1\nvt 1 1\nvn 0 0 2\nf 1/1/1 2/2/1 3/3/1\nf 3/3/1 2/2/1 4/4/1\n");Files.writeString(root.resolve("paint.mtl"),"newmtl Paint\nKd 1 1 1\nmap_Kd paint.png\n");var image=new BufferedImage(4,4,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<4;y++)for(int x=0;x<4;x++)image.setRGB(x,y,x<2?(y<2?0xffff0000:0xff0000ff):(y<2?0xff00ff00:0xffffff00));ImageIO.write(image,"png",root.resolve("paint.png").toFile());byte[] original=Files.readAllBytes(source);
        var ui=new AtomicReference<AssetImportDialog>();var project=new AtomicReference<EditorTopologyProject>();var published=new AtomicReference<String>();var before=new AtomicReference<EditorTopologyProject.State>();var applied=new AtomicReference<EditorTopologyProject.State>();
        try{
            SwingUtilities.invokeAndWait(()->{var dock=new AssetImportDialog(null,published::set);ui.set(dock);try{((JDialog)field(dock,"dialog")).setVisible(true);}catch(Exception e){throw new RuntimeException(e);}dock.loadSource(source);});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();project.set((EditorTopologyProject)field(dock,"topologyProject"));before.set(project.get().snapshot());check(before.get().materials().size()==1&&before.get().faces().stream().allMatch(f->!f.material().isEmpty()),"Human source-aware OBJ/MTL captures actual texture bindings");select(dock);((JComboBox<?>)field(dock,"uvScope")).setSelectedIndex(1);((JSpinner)field(dock,"uvFirst")).setValue(.5);button(dock,"previewUv");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");check(project.get().snapshot()==before.get()&&candidate.description().contains("2 faces"),"Actual human UV island preview preserves native authority");capture(dock,output.resolve("uv-transform-preview.png"));button(dock,"cancelFaceEdit");check(project.get().snapshot()==before.get(),"Human UV cancel retains exact native state");button(dock,"previewUv");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");button(dock,"applyFaceEdit");applied.set(candidate.snapshot());check(project.get().snapshot()==applied.get()&&project.get().snapshot().vertices().equals(before.get().vertices())&&project.get().snapshot().materials().equals(before.get().materials()),"UV Apply installs exact native corners while preserving geometry/PNG");button(dock,"undoMesh");check(project.get().snapshot().equals(before.get()),"Human shared UV undo");button(dock,"redoMesh");check(project.get().snapshot().equals(applied.get()),"Human exact UV redo");}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();select(dock);((JComboBox<?>)field(dock,"uvOperation")).setSelectedItem(EditorTopologyProject.UvTransform.ROTATE);((JSpinner)field(dock,"uvFirst")).setValue(90d);button(dock,"previewUv");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();check(project.get().snapshot()==applied.get(),"Rotation preview is not live state");((JSpinner)field(dock,"uvFirst")).setValue(180d);check(field(dock,"modelingPreview")==null&&project.get().snapshot()==applied.get(),"UV parameter change invalidates candidate without a native edit");button(dock,"saveMesh");check(EditorTopologyProject.open(project.get().documentPath()).snapshot().equals(applied.get()),"Actual human UV Save/fresh native reopen");button(dock,"apply");}catch(Exception e){throw new RuntimeException(e);}});await(()->published.get()!=null);verifyRuntime(published.get(),project.get());
            await(()->{try{return !((Boolean)field(ui.get(),"materialRendering"))&&((JLabel)field(ui.get(),"materialRuntime")).getIcon()!=null;}catch(Exception e){throw new RuntimeException(e);}});SwingUtilities.invokeAndWait(()->{try{var liveWorkspace=field(ui.get(),"materialWorkspace");check(field(liveWorkspace,"state")==project.get().snapshot(),"UV canvas observes exact current authoritative native state");check(field(liveWorkspace,"selectedFace").equals(0L),"UV view and model retain selected actual face0");var displayed=(EditorMeshMaterial)field(liveWorkspace,"material");check(displayed.key().equals(project.get().snapshot().faces().get(0).material()),"UV view uses the assigned native material");var window=(JDialog)field(ui.get(),"materialDialog");var input=(JSpinner)field(ui.get(),"uvFirst");var location=SwingUtilities.convertPoint(input,0,0,window.getContentPane());check(location.x+input.getWidth()<=window.getContentPane().getWidth(),"UV input fits the material inspector without horizontal clipping");capture(ui.get(),output.resolve("uv-transform-material-window.png"));check(ui.get().exportObj(output.resolve("uv-transform.obj.zip")),"Human material-preserving UV export");}catch(Exception e){throw new RuntimeException(e);}});EditorObjBundle.validate(project.get().snapshot(),Files.readAllBytes(output.resolve("uv-transform.obj.zip")));
            Files.copy(project.get().documentPath(),output.resolve("uv-transform.btop"),StandardCopyOption.REPLACE_EXISTING);Files.copy(ImportedAssetLibrary.root().resolve(published.get()+".glb"),output.resolve("uv-transform.glb"),StandardCopyOption.REPLACE_EXISTING);check(Arrays.equals(original,Files.readAllBytes(source)),"UV authoring cannot rewrite original source OBJ");System.out.println("PASS human native UV editing: independent material window, real OBJ/MTL source, face/island preview/cancel/apply/parameter guards, shared history/native save/archive, every actual runtime UV/color and OBJ bundle");
        }finally{SwingUtilities.invokeAndWait(()->{if(ui.get()!=null)try{((JDialog)field(ui.get(),"dialog")).dispose();}catch(Exception e){throw new RuntimeException(e);}});System.setProperty("user.home",oldHome);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
